-- --------------------------------------------------------------------------
-- Address (bus_address)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('0a9d1acb-36d2-52ae-b098-c816fb16f4bb', 'Address', 'Maintain Address records', 'Create, find and maintain Address records. The list shows every Address you have access to — select a row to open it, or use New to add one. Each row is a single Address, described by 17 fields.

Id is unique: no two Address records may share the same value, and a save that would duplicate one is rejected. Address Type, Line1, City, Country Code, Is Primary and Status must be filled in before the record can be saved.

Every Address points at Party, Person, Organization and Location. Choose the linked record from the lookup on those fields rather than typing an identifier. Location refers back to Address, so what you change here can affect that record.

Every save starts as a Draft. The business rules and workflows attached to Address then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. An Address with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('78a0785a-655b-567b-b0ed-fbb646d16486', 'bus_address', 'Address', 'Reusable address master data with explicit rules for ownership, primary selection, lifecycle, and historical transaction evidence. Address is reusable master data, but an address printed on an issued invoice, shipment, order, or other historical document is transaction evidence and must remain reproducible even if the master address changes. Supports Party, Organization, Customer, Supplier, Location, order, fulfillment, invoicing, taxation, shipping, reporting, and integration workflows. Party and Location may reuse an Address. Operational documents should resolve the effective address at transaction time and preserve the result where historical reproduction is required. Address create/update → validate country/geography → validate Party/Location dependency → select effective address → transaction captures address evidence → later master-data changes affect future selection only. Active → inactive/retired. Retirement prevents new normal use but does not remove historical references or snapshots. A Customer changes its billing address. The Customer master now points to the new active address, while already issued Invoices retain the address effective when they were issued.', 'A', FALSE, FALSE, FALSE, TRUE, '0a9d1acb-36d2-52ae-b098-c816fb16f4bb', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('cc24d7eb-ff8d-5294-bd57-62c441bca782', '0a9d1acb-36d2-52ae-b098-c816fb16f4bb', '78a0785a-655b-567b-b0ed-fbb646d16486', 'Address', 'Shows one Address at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 6 fields marked with a red asterisk (*) must have a value before Save will accept the record. Party, Person, Organization and Location are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
