VALUES ('14bb9365-fc76-574e-9b66-f3480115007e', 'c903d7f9-7cab-55db-b7c2-442e26ceafc4', '5f191198-67ea-5b80-825d-9afab23d0fe6', 'Location', 'Shows one Location at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 4 fields marked with a red asterisk (*) must have a value before Save will accept the record. Address and Organization are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
