VALUES ('8ea01f30-2709-5a87-ab3c-1d748a5254af', '5edd09a2-e24a-5697-bb9e-020f11c84480', 'effective_at', 'Effective At', 'Time at which this record becomes effective or evidentially applicable. Establishes temporal business meaning. Lifecycle, audit and reporting. Does not rewrite earlier effective evidence. Optional when lifecycle does not require a separate effective timestamp.', 16, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
