-- --------------------------------------------------------------------------
-- Yard (bus_yard)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c08d7647-3b3d-51c2-842c-8bcd3a0bf4e0', 'Yard', 'Maintain Yard records', 'Create, find and maintain Yard records. The list shows every Yard you have access to — select a row to open it, or use New to add one. Each row is a single Yard, described by 5 fields.

Id and Code are unique: no two Yard records may share the same value, and a save that would duplicate one is rejected. Code, Name, Status and Location must be filled in before the record can be saved.

Every Yard points at Location. Choose the linked record from the lookup on those fields rather than typing an identifier. Container and Yard Block refer back to Yard, so what you change here can affect those records.

Every save starts as a Draft. The business rules and workflows attached to Yard then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Yard with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('28bd9112-3060-51b9-995a-fb2d92a44be4', 'bus_yard', 'Yard', 'Represents the facility-level operational boundary for container storage and handling. Yard is the physical and operational context in which containers enter, occupy storage positions, move between positions, undergo inspection or repair, and eventually leave the facility. It is more specific than Location but broader than a YardBlock or YardSlot. Used by container depots, terminals, inland yards, maintenance facilities, logistics operators, gate systems, yard management systems, capacity planning, and transport integrations. Location provides geographic identity. Yard provides facility semantics. YardBlock → YardBay → YardTier → YardSlot provides progressively finer storage position. Container identifies the equipment. ContainerMovement records movement history. Yard status controls facility-level availability while slot status controls individual placement availability. A yard is planned and configured, activated for operations, potentially suspended during incidents or restrictions, and eventually closed. Suspension or closure changes what new work may be accepted but does not erase historical container, movement, inspection, repair, or gate records. A typical flow is gate-in → equipment identification/inspection → yard allocation → placement in a compatible YardSlot → internal movement as required → inspection/repair or release → pre-dispatch staging → gate-out. Each stage should remain traceable to the yard and its physical position. A container depot operates YARD01. A truck gates in a container, the system identifies its size/type and condition, selects a compatible slot such as Block B / Bay 12 / Tier 3, records the placement, and later moves the container to a repair area. The yard remains the facility context while the slot and movement records provide precise operational history.', 'A', FALSE, FALSE, FALSE, TRUE, 'c08d7647-3b3d-51c2-842c-8bcd3a0bf4e0', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('81a4a912-53a2-52af-9c7b-2b4e5dd06a30', 'c08d7647-3b3d-51c2-842c-8bcd3a0bf4e0', '28bd9112-3060-51b9-995a-fb2d92a44be4', 'Yard', 'Shows one Yard at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 4 fields marked with a red asterisk (*) must have a value before Save will accept the record. Location is a lookup — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b5c6d800-2651-55e5-ad01-147fdace3231', '28bd9112-3060-51b9-995a-fb2d92a44be4', 'id', 'Id', 'The immutable CEDM identity of the managed yard facility. Identifies one operational yard regardless of the containers, blocks, slots, operators, or activities currently associated with it. Used by yard operations, location management, movements, inventory, reporting, access, planning, and integrations to anchor yard-specific records. YardBlock, Location, Container, and yard movement records use the yard as operational context. Configuration changes must not change this identity. Required because subordinate yard structures and operational records need an unambiguous facility identity.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('6c98deab-8b5b-534b-acb6-c690c8a20e75', '28bd9112-3060-51b9-995a-fb2d92a44be4', 'code', 'Code', 'The operational business code used to identify the yard. Provides the concise facility reference used by operators, transport partners, EDI messages, reports, integrations, and searches. Used in gate, movement, inventory, shipment, location, and reporting processes where a yard must be selected or communicated. Code identifies the facility; the YardBlock/YardBay/YardTier/YardSlot hierarchy identifies the exact physical storage position. Required because operational systems need a stable human-facing facility identifier.', 10, 100, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('dd7f4b9a-f226-5510-b85b-fe933cf88586', '28bd9112-3060-51b9-995a-fb2d92a44be4', 'name', 'Name', 'The human-readable name of the yard facility. Identifies the facility in user interfaces, reports, documents, maps, and business communications. Supports operational search and reporting where a descriptive name is preferable to a technical code. Names the facility identified by yardId and code; it is not the technical identity and should not be used as a unique key. Required for clear human interpretation of the facility.', 10, 200, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, TRUE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('a96503ec-d2c8-5947-b4ba-358cab3354b9', '28bd9112-3060-51b9-995a-fb2d92a44be4', 'status', 'Status', 'The controlled operational lifecycle state of the yard. Determines whether the facility is being prepared, accepting normal operations, temporarily restricted, or closed. Controls new allocations, inbound movements, gate activity, planning, and other operational actions. Yard status provides facility-level availability; individual YardSlot status and Container status provide more granular operational constraints. Facility exists in the master model but is not available for normal yard transactions. Facility can perform normal operations subject to capacity, safety, equipment, and process constraints. Normal operations are temporarily restricted because of incidents, maintenance, weather, regulatory action, or another controlled reason. Facility is no longer available for normal operations; closure activities may still be performed under controlled processes. Required because the facility''s ability to accept new work must be explicit.', 1026, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ae05426b-e86c-5a9d-8697-aef25074c7bb', '28bd9112-3060-51b9-995a-fb2d92a44be4', 'location_id', 'Location', 'Associates the yard with its primary geographic or business Location. Provides address, coordinates, jurisdiction, routing, mapping, and regional context. Each yard has exactly one primary Location in this model. Location answers where the facility is; Yard answers what container-yard operational capabilities exist at that location.', 19, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
