VALUES ('6d412030-e61e-5acb-a78a-f1bf1223e23d', '81a4a912-53a2-52af-9c7b-2b4e5dd06a30', '6c98deab-8b5b-534b-acb6-c690c8a20e75', '339edc7b-d7dd-58df-937e-7277c061a79a', 'Code', 'The operational business code used to identify the yard. Provides the concise facility reference used by operators, transport partners, EDI messages, reports, integrations, and searches. Used in gate, movement, inventory, shipment, location, and reporting processes where a yard must be selected or communicated. Code identifies the facility; the YardBlock/YardBay/YardTier/YardSlot hierarchy identifies the exact physical storage position. Required because operational systems need a stable human-facing facility identifier. Required — the record cannot be saved while this is empty. Must be unique: a save is rejected if another Yard already uses this value. Up to 100 characters.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
