INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c64f861d-6c41-50a2-a791-3f9f3be669ba', '85f47d6e-1d12-5ba6-bdc0-f28a21f1d54b', 'ff21d6d0-782b-5ad1-a187-ec798a3ae0ba', '339edc7b-d7dd-58df-937e-7277c061a79a', 'Id', 'The immutable identity of the yard block. Identifies one storage-area subdivision within a specific Yard regardless of later changes to layout, capacity, or operating rules. Used by yard allocation, planning, reporting, navigation, movement planning, and integrations to address an area above bay level. The block belongs to one Yard and contains YardBays; its identity is therefore part of the physical hierarchy but remains stable across configuration changes. Required because every operational storage subdivision must be uniquely addressable. Must be unique: a save is rejected if another Yard Block already uses this value.', 10, 10, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('29010998-c0a8-5850-8997-932dbef33f87', '85f47d6e-1d12-5ba6-bdc0-f28a21f1d54b', '9df9073e-2d35-5a60-a2f9-c7a888236674', '339edc7b-d7dd-58df-937e-7277c061a79a', 'Code', 'The operational code used by people and systems to identify the block. Provides the concise block designation shown on yard maps, operator instructions, dashboards, gate/move messages, and integrations. Used for navigation, slot addressing, capacity reporting, movement planning, and exception handling. The code is interpreted within its parent Yard and should be unique within that yard; it is not the identity of a bay or slot. Required because operators and systems need a practical hierarchical address. Required — the record cannot be saved while this is empty. Up to 50 characters.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('29eedc06-a7b7-5609-8668-67b9bba22135', '85f47d6e-1d12-5ba6-bdc0-f28a21f1d54b', '7c5304e1-80ee-5cd1-97ab-fbb8c03c42aa', '339edc7b-d7dd-58df-937e-7277c061a79a', 'Name', 'A descriptive name for the block used in user-facing operations and reporting. Allows a block to be identified by operational purpose, physical area, or local terminology in addition to its code. Used in yard maps, dashboards, reports, planning screens, and operator interfaces. Describes the same block identified by yardBlockId and code and should not replace those technical/business identifiers. Optional when the operational code is sufficient. Up to 150 characters.', 30, 30, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('7becbdd1-cc79-5268-b4d1-ed314853c7c4', '85f47d6e-1d12-5ba6-bdc0-f28a21f1d54b', 'fbb612aa-4d69-5218-be59-57346211ac38', '57318b9f-2a6b-54e8-835c-025897f56ff2', 'Status', 'The operational availability of the entire block for container storage and movement activity. Determines whether subordinate bays may normally be selected for placement, relocation, or planning. Used by allocation and optimization algorithms to exclude unavailable storage areas. Block status is an upper-level constraint: a BLOCKED or CLOSED block can make otherwise ACTIVE bays and slots unusable for new placement. The block may participate in normal yard operations subject to bay, tier, slot, equipment, safety, and container constraints. The block is temporarily unavailable for normal placement or movement, for example because of maintenance, safety, congestion, inspection, or an incident. The block is administratively or permanently unavailable for normal operations. Required because block availability affects all subordinate storage positions. Required — the record cannot be saved while this is empty.', 40, 40, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
