-- --------------------------------------------------------------------------
-- Yard Bay (bus_yard_bay)
-- --------------------------------------------------------------------------
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('532aa009-5fb9-5735-9e96-499193a0a6df', 'bus_yard_bay', 'Yard Bay', 'Represents the longitudinal storage lane between a yard block and the vertical stacking levels used for container storage. YardBay is a physical and operational addressing level. It groups a sequence of vertically stacked positions and provides a useful unit for capacity planning, traffic analysis, container allocation, and rehandling optimization. Used by yard management, gate and dispatch operations, storage allocation, capacity planning, digital-twin visualization, equipment routing, and container movement optimization. The physical hierarchy is Yard → YardBlock → YardBay → YardTier → YardSlot. Yard identifies the facility; YardBlock defines a major storage area; YardBay defines the longitudinal lane; YardTier defines vertical level; YardSlot identifies the atomic physical position. Container records the equipment being stored, while ContainerMovement records changes in its physical position. A bay is not itself a container position. It is a collection of stack levels and slots. Allocation algorithms can use bay-level characteristics such as distance to gate, crane/equipment access, traffic pattern, container class, expected dwell time, and rehandle risk before selecting a precise slot. A bay may be configured, activated, temporarily blocked, or closed. Blocking or closing a bay prevents new normal placements but does not erase current occupancy. Existing containers may require controlled relocation, and each relocation should produce an auditable ContainerMovement event. Bay is a natural optimization unit for balancing yard density, reducing travel distance, minimizing rehandles, grouping containers by destination or dwell profile, and managing equipment workload. A good placement decision evaluates bay-level cost together with tier/slot availability, stack compatibility, container dimensions, weight, hazardous status, reefer requirements, appointment/dispatch timing, and future retrieval priority. Block B03 contains Bay 12. Bay 12 has five tiers and multiple atomic slots. A container arriving at the depot is evaluated against Bay 12''s access, capacity, compatibility, and future retrieval cost before a precise YardSlot is selected. If Bay 12 becomes blocked for maintenance, existing containers remain associated with their slots while new placements are prevented until the block is resolved.', 'A', FALSE, FALSE, FALSE, TRUE, 'a6c450b3-6f0b-5c71-b5f0-de8050dfb377', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e40d8493-d81d-5740-a898-900d125850fb', 'a6c450b3-6f0b-5c71-b5f0-de8050dfb377', '532aa009-5fb9-5735-9e96-499193a0a6df', 'Yard Bay', 'Shows one Yard Bay at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 4 fields marked with a red asterisk (*) must have a value before Save will accept the record. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 1, 20, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('201164a0-27d7-51ac-9109-f44140079f33', '532aa009-5fb9-5735-9e96-499193a0a6df', 'id', 'Id', 'The immutable identity of the yard bay. Identifies one longitudinal storage lane within a specific YardBlock regardless of changes to layout, numbering, or operational status. Used by yard allocation, movement planning, capacity analysis, digital-yard visualization, and integrations. The bay inherits facility context from YardBlock and provides the parent context for YardTier records. Required because every modeled bay must remain uniquely traceable.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('5a3072ca-cddb-5dd7-9426-4b1a3a70b586', '532aa009-5fb9-5735-9e96-499193a0a6df', 'code', 'Code', 'The operational business code used to identify the bay. Provides the human-facing bay address used by operators, terminal systems, equipment instructions, maps, reports, and integrations. Used in container move instructions, search, visualization, slot addressing, and exception handling. The code is scoped to the parent YardBlock and should not be treated as a globally unique yard address. Required for deterministic operational addressing.', 10, 50, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d71b0d60-92c1-56b5-85b6-bcf95b8808ae', '532aa009-5fb9-5735-9e96-499193a0a6df', 'bay_number', 'Bay Number', 'The ordinal position of the bay within its parent YardBlock. Represents the bay''s longitudinal sequence in the block''s physical addressing scheme. Used for sorting, navigation, visualization, slot-code construction, distance estimation, and movement optimization. It is meaningful within the block; a bayNumber of 12 in two different blocks does not identify the same physical location. Required to provide deterministic physical ordering.', 11, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('34ac2a55-6ee3-5365-a698-4e9957e625b3', '532aa009-5fb9-5735-9e96-499193a0a6df', 'status', 'Status', 'The operational availability of the bay and its subordinate tiers and slots. Determines whether the bay can normally participate in container placement, retrieval, relocation, and planning. Used by allocation and optimization algorithms to eliminate unavailable storage lanes before evaluating individual slots. Bay status is an upper-level constraint. A blocked bay can make otherwise active tiers and slots unavailable for new placement while containers already occupying them remain physically valid. The bay may participate in normal operations subject to tier, slot, container, equipment, safety, and yard rules. The bay is temporarily unavailable for normal placement or movement, for example because of maintenance, safety, congestion, inspection, or an incident. The bay is administratively or physically unavailable for normal operations until an explicit reopening or reconfiguration process occurs. Required because bay availability affects all subordinate storage positions.', 1023, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('26962058-a7d1-55f7-a2ad-7611a91b712f', '532aa009-5fb9-5735-9e96-499193a0a6df', 'block_id', 'Block', 'Places the bay inside its parent YardBlock. Supplies the yard, zoning, operational rules, capacity context, and addressing scope for the bay. Every YardBay belongs to exactly one YardBlock. YardBlock is the planning/storage-area boundary; YardBay is the longitudinal lane within that boundary.', 19, NULL, NULL, FALSE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
