INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('04cf6421-6e1f-5ad3-b9a5-6d6ec7f15223', 'bus_yard_tier', 'Yard Tier', 'Represents one vertical level in a container stack and provides the model''s explicit representation of stacking height and access dependency. YardTier answers the question "how high in this bay is the position?" It is essential for calculating stack height, determining whether equipment can reach a container, and understanding whether retrieving one container requires moving containers above it. Used by yard allocation, crane planning, stacking validation, rehandle optimization, safety controls, capacity planning, digital-twin visualization, and operational reporting. The physical hierarchy is Yard → YardBlock → YardBay → YardTier → YardSlot. YardTier should not be treated as the final location of a container; YardSlot is the atomic position. Container.currentSlot points to the exact position, while ContainerMovement records changes between positions. A higher tier generally implies greater retrieval dependency because containers beneath it can obstruct direct access. Placement algorithms therefore consider tier height together with container weight, allowable stacking, equipment reach, dwell time, expected retrieval order, hazardous/reefer rules, and rehandle cost. A tier can be structurally valid but operationally unusable because of equipment or safety restrictions. A tier can be active, temporarily blocked, or closed. Changing its status must not erase existing occupancy. If containers must be relocated, those relocations are explicit ContainerMovement events and the resulting slot state is updated separately. Bay B03-12 has tiers 1 through 5. A container at Tier 4 is above three lower stack positions. If the Tier 1 container is needed urgently, the yard optimizer may calculate one or more rehandles before retrieval. The tier model therefore directly contributes to movement cost and yard optimization.', 'A', FALSE, FALSE, FALSE, TRUE, '1dd47364-445d-5cef-ba11-0ce9917f1efa', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c1bbe8a3-0216-52eb-8700-45ed733f5b81', '1dd47364-445d-5cef-ba11-0ce9917f1efa', '04cf6421-6e1f-5ad3-b9a5-6d6ec7f15223', 'Yard Tier', 'Shows one Yard Tier at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 3 fields marked with a red asterisk (*) must have a value before Save will accept the record. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 1, 20, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('cb208794-c62d-5129-a606-754fdd115673', '04cf6421-6e1f-5ad3-b9a5-6d6ec7f15223', 'id', 'Id', 'The immutable identity of the vertical tier. Identifies one modeled stack level within a specific YardBay regardless of later operational status changes. Used by yard addressing, stacking rules, capacity calculation, movement planning, visualization, and historical references. YardBay establishes the horizontal lane; YardTier establishes the vertical level; YardSlot identifies the exact physical position. Required because each stack level must be uniquely addressable.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('3ec4431c-cee2-5fea-8304-55604e0c6cbd', '04cf6421-6e1f-5ad3-b9a5-6d6ec7f15223', 'tier_number', 'Tier Number', 'The ordinal vertical level of the tier within its parent YardBay. Expresses how high the tier is in the stack according to the yard''s numbering convention, normally with 1 as the lowest level. Used to validate stack height, determine access dependencies, calculate rehandle risk, generate physical addresses, and instruct yard equipment. Tier number has meaning only within its YardBay; it is not a global location identifier. Required because vertical position is fundamental to container stacking.', 11, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e585706d-f192-58d1-822e-781c3edcebf2', '04cf6421-6e1f-5ad3-b9a5-6d6ec7f15223', 'status', 'Status', 'The operational availability of the entire stack level. Determines whether subordinate positions can normally be used for placement, retrieval, or relocation. Used by allocation, stacking, crane planning, safety, and yard optimization algorithms. Tier status can make all subordinate YardSlots operationally unavailable even if their individual status is ACTIVE. Positions may be used subject to slot, container, equipment, safety, and yard rules. The tier is temporarily unavailable, for example because of equipment reach limits, safety restrictions, inspection, damage, or operational constraints. The tier is administratively unavailable for normal operations until explicitly reactivated or reconfigured. Required because a tier-level restriction propagates to its subordinate positions.', 1027, NULL, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('241b7a29-449a-5b76-aae6-19c6979a27ba', '04cf6421-6e1f-5ad3-b9a5-6d6ec7f15223', 'bay_id', 'Bay', 'Places the tier within its parent YardBay and therefore within the containing block and yard. Provides the physical addressing scope, inherited operating constraints, and relationship to other stack levels in the same bay. Every YardTier belongs to exactly one YardBay. The bay provides horizontal context; the tier provides vertical context.', 19, NULL, NULL, FALSE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
