-- --------------------------------------------------------------------------
-- Yard Slot (bus_yard_slot)
-- --------------------------------------------------------------------------
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b6316597-7105-55dc-8747-f1d5ed46304a', 'bus_yard_slot', 'Yard Slot', 'Represents the final, atomic physical position used to place and retrieve a container in a structured yard. YardSlot answers the operational question "exactly where is this container?" It is the location at which a move becomes physically executable and where occupancy can be validated without ambiguity. Used by yard management, gate operations, dispatch, crane/handling equipment, inventory visibility, container tracking, rehandling optimization, digital twins, and movement execution. The physical hierarchy is Yard → YardBlock → YardBay → YardTier → YardSlot. Container references the current slot, while ContainerMovement records every meaningful relocation. YardSlot should therefore represent current physical state, not the movement history. A valid placement requires the slot to be usable and compatible with the container''s size, type, weight, hazardous classification, reefer requirements, stack rules, equipment access, and yard policy. A sophisticated allocator should also consider expected dwell time, retrieval priority, traffic distance, rehandle probability, and energy/equipment cost. Slot occupancy is current state. When a container moves, the origin becomes available and the destination becomes occupied as part of one controlled movement transaction. Historical positions must remain queryable from ContainerMovement so audit, dwell-time, rehandle, and optimization analysis are not lost. Latitude and longitude enable mapping and route calculations but are supplementary. Hierarchical addressing remains the authoritative operational structure because adjacent slots, stack relationships, and equipment access cannot be inferred reliably from coordinates alone. A slot is configured, may become active and empty, can be reserved for an expected placement, becomes occupied when a container arrives, and returns to empty after a successful departure. It can also be blocked or taken out of service without deleting its historical occupancy. Slot B03-012-04-02 is an EMPTY ground position. The yard optimizer reserves it for an inbound 40-foot container. When the container is physically placed, the slot becomes OCCUPIED and the Container.currentSlot is updated. When the container later moves to a repair area, the movement records the origin and destination and the original slot returns to EMPTY.', 'A', FALSE, FALSE, FALSE, TRUE, '603e9775-3f51-565f-ba7b-3fd7dfcbca3f', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c2a15545-4c4b-5896-9e17-a36bf57c7844', '603e9775-3f51-565f-ba7b-3fd7dfcbca3f', 'b6316597-7105-55dc-8747-f1d5ed46304a', 'Yard Slot', 'Shows one Yard Slot at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 4 fields marked with a red asterisk (*) must have a value before Save will accept the record. Container is a lookup — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 1, 20, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c379c98e-f0ff-57cd-8db7-8bd1d5b36890', 'b6316597-7105-55dc-8747-f1d5ed46304a', 'id', 'Id', 'The immutable CEDM identity of the physical yard position. Identifies one storage position independently of the container currently occupying it. Used by allocation, movement instructions, crane operations, digital-yard visualization, occupancy history, and integrations. Container.currentSlot references the current position while ContainerMovement records historical changes; the slot identity itself does not change when occupancy changes. Required because every executable yard position must have a stable identity.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4e341b45-ba2d-544b-8125-44ddaf513ca8', 'b6316597-7105-55dc-8747-f1d5ed46304a', 'slot_code', 'Slot Code', 'The human-readable operational address of the exact yard position. Provides the address operators use to identify where a container should be placed or retrieved. Used in handheld devices, yard maps, gate/interchange documents, move orders, search, reports, and equipment instructions. Its meaning is derived from the YardBlock, YardBay, YardTier, and local position hierarchy; it is not a substitute for those structural relationships. Required because yard execution needs an unambiguous physical address.', 10, 100, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('776625c2-4ffe-545b-8064-9964ae2f2cc4', 'b6316597-7105-55dc-8747-f1d5ed46304a', 'position', 'Position', 'The ordinal horizontal position of the slot within its parent YardTier according to the yard''s addressing convention. Distinguishes adjacent storage positions on the same tier and provides deterministic placement/navigation. Used for physical addressing, yard visualization, movement planning, and layout validation. Position is scoped to the parent tier and should not be interpreted as a global coordinate or geographic distance. Required to identify the exact position within the tier.', 11, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('85684928-db51-5c13-960f-66b9f43df3d7', 'b6316597-7105-55dc-8747-f1d5ed46304a', 'status', 'Status', 'The current operational state of the storage position. Determines whether the position is available, physically occupied, preallocated, temporarily restricted, or physically unavailable. Drives allocation, movement validation, yard optimization, equipment dispatch, and exception handling. OCCUPIED represents actual current placement; RESERVED represents intended future placement; BLOCKED and OUT_OF_SERVICE prevent normal placement regardless of whether the position is physically empty. Physically available for a valid container placement. Currently occupied by exactly one container. Held for an expected move or planned placement but not yet physically occupied. Temporarily unavailable because of an operational restriction such as traffic, safety, inspection, congestion, or local control. Physically or administratively unavailable for an extended reason such as damage, maintenance, construction, or reconfiguration. Required because slot state is an execution constraint for every placement or relocation.', 1025, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('f029cc1c-e9c0-5c66-8109-9ce6fe248811', 'b6316597-7105-55dc-8747-f1d5ed46304a', 'latitude', 'Latitude', 'The geographic latitude of the physical slot or its defined mapping reference point. Allows the atomic yard position to participate in geospatial visualization and route calculations. Used by digital twins, mapping, equipment routing, geospatial analysis, and integration with external mapping services. Coordinates complement hierarchical addressing and should correspond to the same physical position represented by slotCode. Optional where the yard operates entirely from a logical grid or local coordinate system.', 12, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('57c4e20b-24a3-5991-9614-cd56d2f3492a', 'b6316597-7105-55dc-8747-f1d5ed46304a', 'longitude', 'Longitude', 'The geographic longitude of the physical slot or its defined mapping reference point. Completes the geographic coordinate for the exact storage position. Used with latitude for mapping, visualization, route calculation, and geospatial analysis. Longitude must describe the same physical reference point as latitude and does not replace the operational hierarchy. Optional where geographic coordinates are not maintained at slot level.', 12, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('fb5d2c47-706b-5692-b2c4-0cd376ceeb00', 'b6316597-7105-55dc-8747-f1d5ed46304a', 'tier_id', 'Tier', 'Places the slot within its parent YardTier and therefore determines its complete physical yard hierarchy. Used to derive bay, block, and yard context and validate addressing and stacking rules. Every YardSlot belongs to exactly one YardTier. Tier provides vertical context; position supplies local horizontal context; together with the parent hierarchy they identify the atomic storage address.', 19, NULL, NULL, FALSE, TRUE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 70, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('dc3b93f5-4089-5b10-998f-0fa97da1c4cc', 'b6316597-7105-55dc-8747-f1d5ed46304a', 'container_id', 'Container', 'Identifies the container currently occupying the slot. Used for current yard visibility, retrieval planning, inventory lookup, movement validation, and operator instructions. At most one container may occupy a slot at a time. This is current-state occupancy. Historical occupants and previous locations must be derived from ContainerMovement rather than overwritten in this relationship.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 80, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
UPDATE sys_column SET ref_table_name = 'bus_yard_tier' WHERE sys_column_id = 'fb5d2c47-706b-5692-b2c4-0cd376ceeb00';
UPDATE sys_tab SET link_column_id = 'fb5d2c47-706b-5692-b2c4-0cd376ceeb00' WHERE sys_tab_id = 'c2a15545-4c4b-5896-9e17-a36bf57c7844';
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('64c7a15d-9f1b-529c-af66-2362c73b79d0', 'c2a15545-4c4b-5896-9e17-a36bf57c7844', 'c379c98e-f0ff-57cd-8db7-8bd1d5b36890', '339edc7b-d7dd-58df-937e-7277c061a79a', 'Id', 'The immutable CEDM identity of the physical yard position. Identifies one storage position independently of the container currently occupying it. Used by allocation, movement instructions, crane operations, digital-yard visualization, occupancy history, and integrations. Container.currentSlot references the current position while ContainerMovement records historical changes; the slot identity itself does not change when occupancy changes. Required because every executable yard position must have a stable identity. Must be unique: a save is rejected if another Yard Slot already uses this value.', 10, 10, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c2da401e-e150-53ce-bb0e-0854091fb4ca', 'c2a15545-4c4b-5896-9e17-a36bf57c7844', '4e341b45-ba2d-544b-8125-44ddaf513ca8', '339edc7b-d7dd-58df-937e-7277c061a79a', 'Slot Code', 'The human-readable operational address of the exact yard position. Provides the address operators use to identify where a container should be placed or retrieved. Used in handheld devices, yard maps, gate/interchange documents, move orders, search, reports, and equipment instructions. Its meaning is derived from the YardBlock, YardBay, YardTier, and local position hierarchy; it is not a substitute for those structural relationships. Required because yard execution needs an unambiguous physical address. Required — the record cannot be saved while this is empty. Up to 100 characters.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('47a48e50-f547-5f1d-9f05-7786ebba835f', 'c2a15545-4c4b-5896-9e17-a36bf57c7844', '776625c2-4ffe-545b-8064-9964ae2f2cc4', '339edc7b-d7dd-58df-937e-7277c061a79a', 'Position', 'The ordinal horizontal position of the slot within its parent YardTier according to the yard''s addressing convention. Distinguishes adjacent storage positions on the same tier and provides deterministic placement/navigation. Used for physical addressing, yard visualization, movement planning, and layout validation. Position is scoped to the parent tier and should not be interpreted as a global coordinate or geographic distance. Required to identify the exact position within the tier. Required — the record cannot be saved while this is empty.', 30, 30, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('59119979-83d8-5228-b863-12d0f4f1e005', 'c2a15545-4c4b-5896-9e17-a36bf57c7844', '85684928-db51-5c13-960f-66b9f43df3d7', '57318b9f-2a6b-54e8-835c-025897f56ff2', 'Status', 'The current operational state of the storage position. Determines whether the position is available, physically occupied, preallocated, temporarily restricted, or physically unavailable. Drives allocation, movement validation, yard optimization, equipment dispatch, and exception handling. OCCUPIED represents actual current placement; RESERVED represents intended future placement; BLOCKED and OUT_OF_SERVICE prevent normal placement regardless of whether the position is physically empty. Physically available for a valid container placement. Currently occupied by exactly one container. Held for an expected move or planned placement but not yet physically occupied. Temporarily unavailable because of an operational restriction such as traffic, safety, inspection, congestion, or local control. Physically or administratively unavailable for an extended reason such as damage, maintenance, construction, or reconfiguration. Required because slot state is an execution constraint for every placement or relocation. Required — the record cannot be saved while this is empty.', 40, 40, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b8ba18a4-ddb2-5443-ab54-bccb5384a37a', 'c2a15545-4c4b-5896-9e17-a36bf57c7844', 'f029cc1c-e9c0-5c66-8109-9ce6fe248811', '57318b9f-2a6b-54e8-835c-025897f56ff2', 'Latitude', 'The geographic latitude of the physical slot or its defined mapping reference point. Allows the atomic yard position to participate in geospatial visualization and route calculations. Used by digital twins, mapping, equipment routing, geospatial analysis, and integration with external mapping services. Coordinates complement hierarchical addressing and should correspond to the same physical position represented by slotCode. Optional where the yard operates entirely from a logical grid or local coordinate system.', 50, 50, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('cba4d815-9cef-50ee-8bfe-03e2b62dd5e7', 'c2a15545-4c4b-5896-9e17-a36bf57c7844', '57c4e20b-24a3-5991-9614-cd56d2f3492a', '57318b9f-2a6b-54e8-835c-025897f56ff2', 'Longitude', 'The geographic longitude of the physical slot or its defined mapping reference point. Completes the geographic coordinate for the exact storage position. Used with latitude for mapping, visualization, route calculation, and geospatial analysis. Longitude must describe the same physical reference point as latitude and does not replace the operational hierarchy. Optional where geographic coordinates are not maintained at slot level.', 60, 60, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b0151a70-307d-5f24-a599-c0208976db31', 'c2a15545-4c4b-5896-9e17-a36bf57c7844', 'fb5d2c47-706b-5692-b2c4-0cd376ceeb00', '57318b9f-2a6b-54e8-835c-025897f56ff2', 'Tier', 'Places the slot within its parent YardTier and therefore determines its complete physical yard hierarchy. Used to derive bay, block, and yard context and validate addressing and stacking rules. Every YardSlot belongs to exactly one YardTier. Tier provides vertical context; position supplies local horizontal context; together with the parent hierarchy they identify the atomic storage address. Required — the record cannot be saved while this is empty.', 70, 70, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('63d30e2d-6694-51c8-8f86-771c0d01fee9', 'c2a15545-4c4b-5896-9e17-a36bf57c7844', 'dc3b93f5-4089-5b10-998f-0fa97da1c4cc', '57318b9f-2a6b-54e8-835c-025897f56ff2', 'Container', 'Identifies the container currently occupying the slot. Used for current yard visibility, retrieval planning, inventory lookup, movement validation, and operator instructions. At most one container may occupy a slot at a time. This is current-state occupancy. Historical occupants and previous locations must be derived from ContainerMovement rather than overwritten in this relationship.', 80, 80, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
