INSERT INTO sys_category (sys_category_id, name, code, description, icon, color, seq_no, is_default, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('49b4013a-e4a5-572c-bf39-8c2866ece84f', 'Container and Intermodal Logistics', 'container-and-intermodal-logistics', NULL, 'container', NULL, 1, FALSE, TRUE, 'system', 'system', NOW(), NOW())
